#define clamp(var, min, max, res) { \
    if (var < min) {                \
        res =  min;                 \
    };                              \
                                    \
    if (var > max) {                \
        res =  max;                 \
    };                              \
                                    \
    res = var;                      \
}  

#define next_color(color, color_count, res) {  \
    if (color + 1 < color_count) {             \
        color = color + 1;                     \
        res = color;                           \
    } else {                                   \
        res =  0;                              \
    };                                         \
}

